INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64506984', 64506984, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN PRIMER DAN KOMUNITAS', 'Pompa Infus Tahap 2', 'Barang', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 25796054000, 'January 2026', 'APBN - RUPIAH MURNI (A), APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '4616', 'Pompa Infus Tahap 2', 'Infusion pumps designed to deliver different types of liquid medications and other solutions through intravenous (IV), epidural, and/or subcutaneous routes at pre-established accurate flow rates capable of being used in a variety of different therapies (i.e., multitherapy). These pumps may be intended to deliver large and/or small volumes of liquids; some pumps can deliver infusion liquids through only one channel (i.e., single-channel pumps) or simultaneously using several channels (i.e., multi-channel pumps). Pumps capable of delivering high volumes of infusion solutions usually consist of pole-mounted devices that include a pumping (e.g., peristaltic, cassette) mechanism to move fluid from the solution container through the IV set to the patient. Other pumps using syringe-based mechanisms are usually intended to deliver smaller volumes. The pumps may also include controls to select the dose or volume to be infused; recording capabilities to register the actual infusion volume and rate; and audible and/or visual alarms to indicate abnormal or dangerous conditions. Some pumps (known as "smart pumps") include software capable of detecting medication administration errors (i.e., dose error reduction systems) are also available. Multitherapy infusion pumps are used mainly in hospitals and other healthcare facilities, in doctors\' offices, and at home.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1576198);
