INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64507539', 64507539, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN PRIMER DAN KOMUNITAS', 'Elektrokardiograf Tahap 2', 'Barang', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 23393251000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '2244 units', 'Elektrokardiograf Tahap 2', 'Multichannel electrocardiographs (ECGs) designed for recording the variations of the electric potential caused by the electrical activity of the heart muscle, usually detected at the body surface from two or more leads simultaneously that can perform a computerized automated measuring and interpretation of the ECG. These instruments include a computerized unit that can process the ECG signals, compare those signals with an internal algorithm, and print out the ECG along with an interpretation that can be used as an auxiliary tool by the cardiologist; some instruments can also provide a vectorcardiogram. Instruments that can perform the measuring and interpretation of the ECGs by averaging multiple cycles of the signal are also available. Interpretative multichannel electrocardiographs are not intended for a real-time assessment of the electrocardiogram or other cardiac conditions.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1577021);
